:host {
  display: block;
  height: 100dvh;
}

.shell {
  display: flex;
  height: 100%;
  overflow: hidden;
}

// ─── Sidebar ─────────────────────────────────────────────────────────────────

.sidebar {
  width: 200px;
  flex-shrink: 0;
  background: #0B1F33; // Seqera dark navy
  color: rgba(255, 255, 255, 0.85);
  display: flex;
  flex-direction: column;
  padding: 16px 0;
  gap: 8px;
}

.sidebar__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 16px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.sidebar__logo-text {
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.01em;
}

.sidebar__nav {
  list-style: none;
  padding: 8px 8px 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.sidebar__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: var(--radius);
  color: rgba(255, 255, 255, 0.7);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  transition: background var(--motion-fast) var(--ease-out),
              color var(--motion-fast) var(--ease-out);

  .material-icons {
    font-size: 18px;
  }

  &:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #fff;
  }

  &:focus-visible {
    outline: 2px solid var(--c-primary);
    outline-offset: 2px;
  }

  &--active {
    background: rgba(66, 86, 231, 0.35);
    color: #fff;
  }
}

.sidebar__footer {
  padding: 12px 16px 4px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.sidebar__version {
  font-size: 0.7rem;
  color: rgba(255, 255, 255, 0.35);
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

// ─── Main content ─────────────────────────────────────────────────────────────

.main-content {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  background: var(--c-bg);
  display: flex;
  flex-direction: column;
}

