:host {
  display: block;
  min-width: 0;
}

.kpi-card {
  display: flex;
  width: 100%;
  min-width: 128px;
  min-height: 112px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 6px;
  padding: 16px;
  color: var(--c-text);
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  font-family: inherit;
  text-align: left;
  transition:
    transform 140ms cubic-bezier(0.2, 0.8, 0.2, 1),
    border-color 140ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 140ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

button.kpi-card {
  cursor: pointer;

  &:hover {
    box-shadow: 0 5px 14px rgb(11 31 51 / 9%);
    transform: translateY(-2px);
  }

  &:focus-visible {
    outline: 3px solid var(--c-primary);
    outline-offset: 2px;
  }
}

.kpi-card--pressed {
  border-color: var(--c-primary);
  box-shadow: 0 0 0 3px rgb(66 86 231 / 17%);
}

.kpi-card__topline {
  display: flex;
  width: 100%;
  gap: 7px;
  align-items: center;
}

.kpi-card__tone {
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  background: #64748b;
  border-radius: 50%;
}

.kpi-card__label {
  overflow: hidden;
  color: #526477;
  font-size: 0.75rem;
  font-weight: 650;
  letter-spacing: 0.025em;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kpi-card__badge {
  display: inline-grid;
  width: 18px;
  height: 18px;
  margin-left: auto;
  place-items: center;
  color: #fff;
  background: var(--c-fail);
  border-radius: 50%;
  font-size: 0.7rem;
  font-weight: 750;
  line-height: 1;
}

.kpi-card__value {
  color: #475569;
  font-size: 1.65rem;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
}

.kpi-card__sub {
  overflow: hidden;
  max-width: 100%;
  color: #5d6d7e;
  font-size: 0.72rem;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kpi-card--ok {
  .kpi-card__tone {
    background: var(--c-ok);
  }

  .kpi-card__value {
    color: var(--c-ok-text);
  }
}

.kpi-card--fail {
  .kpi-card__tone {
    background: var(--c-fail);
  }

  .kpi-card__value {
    color: var(--c-fail-text);
  }
}

.kpi-card--run {
  .kpi-card__tone {
    background: var(--c-run);
  }

  .kpi-card__value {
    color: var(--c-run-text);
  }
}

.kpi-card--attention {
  .kpi-card__tone {
    background: var(--c-warn);
  }

  .kpi-card__value {
    color: var(--c-warn-text);
  }
}

.kpi-card--cost {
  .kpi-card__tone {
    background: var(--c-accent-violet);
  }

  .kpi-card__value {
    color: #6d3fc0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .kpi-card {
    transition: none;
  }
}

