        [kpis]="kpis()"
        [activeFilter]="statusFilter()"
        (filter)="onStatusFilter($event)" />

      <!-- Search + filter row -->
      <div class="page__filters" role="search">
        <div class="search-field">
          <span class="material-icons search-field__icon" aria-hidden="true">search</span>
          <input
            type="search"
            class="search-field__input"
            placeholder="Search runs, pipelines, users…"
            aria-label="Search runs"
            [value]="search()"
            (input)="onSearch($event)" />
        </div>
      </div>

      <!-- Global error state -->
      @if (runsService.loadStatus() === 'error') {
        <div class="page__error" role="alert">
          <span class="material-icons" aria-hidden="true">error_outline</span>
          <div>
            <strong>Failed to load runs</strong>
            <p>Could not fetch the dataset. Check that the JSON file is available.</p>
          </div>
        </div>
      }

      <!-- Runs table (also owns loading + empty states) -->
      <div class="page__table">
        <app-runs-table
          [runs]="visibleRuns()"
          [selectedId]="selectedId()"
          [loading]="runsService.loadStatus() === 'loading'"
          [sort]="sort()"
          (select)="selectedId.set($event.id)"
          (sortChange)="sort.set($event)"
          (clearFilters)="resetFilters()" />
      </div>

      <!-- Detail drawer (overlay, mounted at page root for stacking) -->
      <app-run-drawer
        [run]="selectedRun()"
        (close)="selectedId.set(null)" />

    </div>
  `,
  styleUrl: './runs-page.component.scss',
})
export class RunsPageComponent implements OnDestroy {
  protected readonly runsService = inject(RunsService);
  private readonly route = inject(ActivatedRoute);

  // ─── View state ───────────────────────────────────────────────────────────

  protected readonly search = signal('');
  protected readonly statusFilter = signal<RunStatus | null>(null);
  protected readonly sort = signal<SortState>({ key: 'risk', dir: 'desc' });
  protected readonly selectedId = signal<string | null>(null);

  private readonly routeData = toSignal(this.route.data);

  protected readonly scenario = computed<'sample' | 'showcase'>(() =>
    (this.routeData()?.['scenario'] as 'sample' | 'showcase') ?? 'showcase'
  );

  constructor() {
    // Re-load when scenario changes (route switch /sample ↔ /showcase)
    effect(() => {
      this.runsService.load(this.scenario());
      this.resetFilters();
      this.selectedId.set(null);
    });
  }

  ngOnDestroy(): void {
    // No teardown needed — RunsService is root-provided
  }

  // ─── Derived state ────────────────────────────────────────────────────────

  protected readonly visibleRuns = computed(() => {
    let runs: RunDetailVM[] = this.runsService.runs();
    const search = this.search().trim().toLowerCase();
    const status = this.statusFilter();

    if (search) {
      runs = runs.filter(r =>
        r.name.toLowerCase().includes(search) ||
        r.pipeline.toLowerCase().includes(search) ||
        (r.user?.toLowerCase().includes(search) ?? false)
      );
    }

    if (status) {
      runs = runs.filter(r => r.status === status);
    }

    return sortRuns(runs, this.sort());
  });

  protected readonly kpis = computed<KpiStats>(() => {
    const runs = this.runsService.runs();
    const counts = { FAILED: 0, SUCCEEDED: 0, RUNNING: 0, SUBMITTED: 0, CANCELLED: 0 };
    let needsAttention = 0;
    let totalCost = 0;

    for (const run of runs) {
      counts[run.status]++;
      if (run.needsAttention) needsAttention++;
      totalCost += run.cost ?? 0;
    }

    return { ...counts, needsAttention, total: runs.length, totalCost };
  });

  protected readonly selectedRun = computed<RunDetailVM | null>(() =>
    this.runsService.runs().find(r => r.id === this.selectedId()) ?? null
  );

  // ─── Event handlers ───────────────────────────────────────────────────────

  protected onSearch(event: Event): void {
    this.search.set((event.target as HTMLInputElement).value);
  }

  protected onStatusFilter(status: RunStatus | null): void {
    this.statusFilter.set(status);
  }

  protected resetFilters(): void {
    this.search.set('');
    this.statusFilter.set(null);
  }
}

