    background: var(--c-border);
    gap: 1px;
  }

  &__seg {
    min-width: 0;
    transition: flex 0.3s ease;

    &--succeeded { background: var(--c-ok); }
    &--failed    { background: var(--c-fail); }
    &--aborted   { background: var(--c-warn); }
    &--cached    { background: var(--c-run); }
    &--running   { background: var(--c-run); opacity: 0.5; }
  }

  &__count {
    font-size: 0.8rem;
    color: var(--c-text-muted);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    flex-shrink: 0;
  }

  &__empty {
    font-size: 0.8rem;
    color: var(--c-text-muted);
    white-space: nowrap;
  }
}

